#define EMBER_SIMD_EACH_2(MAC, F) MAC(F, 0) MAC(F, 1)
#define EMBER_SIMD_EACH_4(MAC, F) MAC(F, 0) MAC(F, 1) MAC(F, 2) MAC(F, 3)
