#define EMBER_SIMD_LOAD_K_double(F, k) r.v[k] = _mm_loadu_pd((const double*)s.ptr + 2 * (k));
#define EMBER_SIMD_LOAD_K_int(F, k) r.v[k] = _mm_loadu_si128((const __m128i*)s.ptr + (k));
#define EMBER_SIMD_STORE_K_float(F, k) _mm_storeu_ps((float*)s.ptr + 4 * (k), v.v[k]);
#define EMBER_SIMD_STORE_K_double(F, k) _mm_storeu_pd((double*)s.ptr + 2 * (k), v.v[k]);
