/* -- what every vector type has ------------------------------------------ */

#define EMBER_SIMD_COMMON(V, T, N, M, MT, KIND, C)                                              \
    EMBER_SIMD_MEMORY(V, T, N, KIND, C)                                                         \
    EMBER_SIMD_FN V V##_shuffle(V v, const int64_t* lanes) {                                    \
